version.content:
pipeline {
    agent any

    environment {
        GROUP_NAME = null
        PROJECT_NAME = null
        VERSION = null
        PORT = 11015
        REMOTE_HOST = '10.0.0.22' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key' // Jenkins中保存的远程服务器SSH凭证ID
        BES_REMOTE_HOST = '10.0.0.62' // 远程服务器地址
        BES_REMOTE_USER = 'root' // 远程服务器用户名
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
        REMOTE_DIR = '/data/dsj/bes/server'  // 远程服务器上的目标目录
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit (branches: [[name:
                "${params.Branch}"]],extensions: [],userRemoteConfigs: [[credentialsId:
                'SSH-KEY-FOR-GITLAB', url:'ssh://git@106.227.89.18:10093/yzt/lead-analytics.git']])
            }
        }

        stage('Mvn Compile') {
            steps {
                script {
                    def pom = readMavenPom file:
                    'pom.xml'
                    GROUP_NAME = pom.groupId
                    PROJECT_NAME = pom.artifactId
                    VERSION = pom.version
                    echo "PROJECT_NAME：${PROJECT_NAME}"
                    sh "mvn clean"
                    sh "mvn install -Dmaven.test.skip=true -Ptest"
                }
            }
        }


        stage('Rename Backup') {
            steps {
                script {
                    // 切换至远程服务器，备份原有jar包
                    def jarName = "${PROJECT_NAME}-${VERSION}" // 根据项目名称和版本构造 war 包名

                    sh """
                        ssh ${REMOTE_USER}@${BES_REMOTE_HOST} '
                            cd ${REMOTE_DIR}

                            if [ -e "analytics-server-${VERSION}.war" ]; then
                                mv  "analytics-server-${VERSION}.war"  "analytics-server-${VERSION}.war-${TIMESTAMP}" 
                            fi

                        '
                    """
                }
            }
        }


        stage('Copy to Bes Server') {
            steps {
                script {
                    def jarName = "${PROJECT_NAME}-${VERSION}.war" // 根据项目名称和版本构造 war 
                    def jobName = env.JOB_NAME
                    def currentWorkspace = pwd()
                    echo "jarName：${jarName}"
                    echo "当前工作空间：${currentWorkspace}"

                    // 将 war 包复制到远程服务器
                    sh "scp ${currentWorkspace}/analytics-server/target/analytics-server-${VERSION}.war ${REMOTE_USER}@${BES_REMOTE_HOST}:${REMOTE_DIR}"
                }
            }
        }


        stage('Deploy to Remote Server') {
            steps {
                script {

                     // 在bes服务器上执行命令
                    sh """
                        ssh ${REMOTE_USER}@${BES_REMOTE_HOST} '

                            cd /data/seeyon/products/bes/bin && 

                           ./iastool --passport B#2008_2108#es --user admin --password B#2008_2108#es undeploy analytics-server  || true &&

                           ./iastool --passport B#2008_2108#es --user admin --password B#2008_2108#es deploy --name analytics-server --target lead-analytics-instance01 --contextroot /lead-analytics-test /data/dsj/bes/server/analytics-server-1.0-SNAPSHOT.war


                        '
                    """   

                }
            }
        }

    }

}
